-- Migration 0015_billing_dunning: generated by drizzle-kit (the columns and check), function hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #205)
-- Dunning (#28 part 6):
--   * subscription.dunning_started_at (nullable) marks when the current dunning episode began
--     (first failed charge or halt); subscription.dunning_attempts counts the payment retries made
--     in it (0..4). The `billing.process-event` job starts and clears them; the
--     `system.billing.dunning-tick` job advances them.
--   * app_billing_dunning_targets() lists the ids of every `past_due` subscription (which covers
--     grace: past_due with grace_until). The tick has no workspace and `subscription` is under
--     FORCE row-level security, so it lists its targets through this owner-defined SECURITY
--     DEFINER function (reading via owner_definer_read from 0007), then reads each row inside
--     withWorkspace. Ids only.
--   * Additive only; the previous release never reads the columns or calls the function.
ALTER TABLE "subscription" ADD COLUMN "dunning_started_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "subscription" ADD COLUMN "dunning_attempts" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "subscription" ADD CONSTRAINT "subscription_dunning_attempts_chk" CHECK (dunning_attempts between 0 and 4);--> statement-breakpoint
CREATE FUNCTION app_billing_dunning_targets()
  RETURNS TABLE (workspace_id uuid, subscription_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT s.workspace_id, s.id FROM subscription s
    WHERE s.status = 'past_due'
    ORDER BY s.workspace_id, s.id
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_billing_dunning_targets() FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_billing_dunning_targets() TO causedeck_app;
